"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  INTERACTION_PRESS,
  interactionIcon,
} from "./imported-ui-interaction-motion";

export type ButtonVariant =
  | "primary"
  | "brand"
  | "secondary"
  | "outline"
  | "ghost"
  | "destructive"
  | "link";

export type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon";
export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  loading?: boolean;
  status?: ActionStatus;
  /** Custom labels for each state when using status/async flows. */
  statusLabels?: Partial<Record<ActionStatus, string>>;
  /** Automatically reset back to idle after success/error (ms). Default 1800ms. */
  resetAfter?: number;
  onReset?: () => void;
  icon?: React.ReactNode;
  trailingIcon?: React.ReactNode;
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const variantStyles: Record<ButtonVariant, string> = {
  primary: "bg-primary text-primary-foreground hover:bg-primary/90",
  brand: "bg-primary text-primary-foreground hover:bg-primary/90",
  secondary:
    "bg-card text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent",
  outline:
    "bg-transparent text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent",
  ghost:
    "bg-transparent text-muted-foreground hover:bg-accent hover:text-foreground",
  destructive:
    "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400 hover:bg-red-500/15",
  link: "bg-transparent text-primary underline-offset-4 hover:underline p-0 h-auto font-normal",
};

interface SizeConfig {
  height: string;
  padding: string;
  fontSize: string;
  iconSize: number;
  iconGap: number;
}

const sizeConfigs: Record<ButtonSize, SizeConfig> = {
  xs: {
    height: "h-6",
    padding: "px-2.5",
    fontSize: "text-[12px]",
    iconSize: 12,
    iconGap: 5,
  },
  sm: {
    height: "h-7",
    padding: "px-3",
    fontSize: "text-[12px]",
    iconSize: 13,
    iconGap: 6,
  },
  md: {
    height: "h-9",
    padding: "px-4",
    fontSize: "text-[13px]",
    iconSize: 14,
    iconGap: 7,
  },
  lg: {
    height: "h-10",
    padding: "px-5",
    fontSize: "text-[14px]",
    iconSize: 16,
    iconGap: 8,
  },
  icon: {
    height: "size-9 p-0 justify-center items-center shrink-0",
    padding: "p-0",
    fontSize: "text-[13px]",
    iconSize: 15,
    iconGap: 0,
  },
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function SelfDrawingCheck({
  drawn,
  reduced,
  size,
}: {
  drawn: boolean;
  reduced: boolean;
  size: number;
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      className="shrink-0"
    >
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE_OUT} 100ms`
              : "none",
        }}
      />
    </svg>
  );
}

function StatusAlert({ size }: { size: number }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      className="shrink-0"
    >
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

const DEFAULT_LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};

/**
 * Button: high-craft tactile action primitive with rounded-full pill geometry,
 * StatusButton visual parity, self-drawing checkmark morphs, TextMorph label transitions,
 * and error shake physics.
 */
export function Button({
  ref,
  variant = "primary",
  size = "md",
  loading = false,
  status,
  statusLabels,
  resetAfter = 1800,
  onReset,
  disabled = false,
  icon,
  trailingIcon,
  className = "",
  children,
  onClick,
  ...props
}: ButtonProps) {
  const innerRef = React.useRef<HTMLButtonElement | null>(null);
  const reduced = useReducedMotion();

  React.useImperativeHandle(ref, () => innerRef.current as HTMLButtonElement);

  // Normalize status from explicit prop or loading boolean
  const currentStatus: ActionStatus = status ?? (loading ? "pending" : "idle");
  const isAsyncFlow = status !== undefined || loading;

  // Resolve current text label
  const idleLabel =
    typeof children === "string" ? children : DEFAULT_LABELS.idle;
  const labels: Record<ActionStatus, string> = {
    idle: statusLabels?.idle ?? idleLabel,
    pending: statusLabels?.pending ?? DEFAULT_LABELS.pending,
    success: statusLabels?.success ?? DEFAULT_LABELS.success,
    error: statusLabels?.error ?? DEFAULT_LABELS.error,
  };
  const activeLabel = labels[currentStatus];

  // Auto-reset timer for success or error states
  React.useEffect(() => {
    if ((currentStatus !== "success" && currentStatus !== "error") || !onReset)
      return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [currentStatus, onReset, resetAfter]);

  // Error state horizontal shake
  React.useEffect(() => {
    if (currentStatus !== "error" || reduced) return;
    innerRef.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [currentStatus, reduced]);

  const cfg = sizeConfigs[size];
  const isBusy = currentStatus === "pending";
  const isInert = disabled || isBusy;

  // Icon slot state: open if an icon was provided, or if in async status
  const showLeadingSlot =
    size !== "icon" &&
    (Boolean(icon) || (isAsyncFlow && currentStatus !== "idle"));

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    pending: (
      <span
        style={{ width: cfg.iconSize, height: cfg.iconSize }}
        className={`rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none opacity-85 ${
          currentStatus === "pending" ? "animate-spin" : ""
        }`}
      />
    ),
    success: (
      <span
        className={
          variant === "primary"
            ? "text-primary-foreground"
            : "text-emerald-600 dark:text-emerald-400"
        }
      >
        <SelfDrawingCheck
          drawn={currentStatus === "success"}
          reduced={reduced}
          size={cfg.iconSize}
        />
      </span>
    ),
    error: (
      <span className="text-red-600 dark:text-red-400">
        <StatusAlert size={cfg.iconSize} />
      </span>
    ),
  };

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (isInert) {
      e.preventDefault();
      return;
    }
    onClick?.(e);
  };

  // Tone shifts for error states
  const toneClass =
    currentStatus === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variantStyles[variant];

  return (
    <>
      <button
        ref={innerRef}
        type={props.type ?? "button"}
        disabled={disabled}
        aria-disabled={isInert ? true : undefined}
        aria-busy={isBusy ? true : undefined}
        onClick={handleClick}
        className={`relative inline-flex items-center justify-center font-medium select-none whitespace-nowrap cursor-pointer rounded-full disabled:cursor-default disabled:opacity-45 ${variant === "link" ? "transition-colors" : INTERACTION_PRESS} ${FOCUS} ${
          toneClass
        } ${cfg.height} ${cfg.padding} ${cfg.fontSize} ${className}`}
        {...props}
      >
        {/* Leading Icon / Status Slot with explicit width, height, and marginRight */}
        {size !== "icon" && (
          <span
            aria-hidden="true"
            className="relative flex shrink-0 items-center justify-center overflow-hidden"
            style={{
              width: showLeadingSlot ? cfg.iconSize : 0,
              height: cfg.iconSize,
              marginRight: showLeadingSlot ? cfg.iconGap : 0,
              transition: reduced
                ? "none"
                : `width 360ms ${EASE_OUT}, margin-right 360ms ${EASE_OUT}`,
            }}
          >
            {(Object.keys(icons) as ActionStatus[]).map((st) => (
              <span
                key={st}
                className="absolute inset-0 flex items-center justify-center"
                style={interactionIcon(st === currentStatus, reduced)}
              >
                {icons[st]}
              </span>
            ))}
          </span>
        )}

        {/* Icon-only mode: the same stacked layers, so the icon never hard-swaps. */}
        {size === "icon" && (
          <span
            aria-hidden="true"
            className="relative shrink-0"
            style={{ width: cfg.iconSize, height: cfg.iconSize }}
          >
            {(Object.keys(icons) as ActionStatus[]).map((st) => (
              <span
                key={st}
                className="absolute inset-0 flex items-center justify-center"
                style={interactionIcon(st === currentStatus, reduced)}
              >
                {st === "idle" ? (icon ?? children) : icons[st]}
              </span>
            ))}
          </span>
        )}

        {/* Text Label: uses TextMorph for silky label transitions */}
        {size !== "icon" && (
          <span className="inline-flex items-center">
            {typeof children === "string" || isAsyncFlow ? (
              <TextMorph>{activeLabel}</TextMorph>
            ) : (
              children
            )}
          </span>
        )}

        {/* Trailing Icon with guaranteed calibrated spacing */}
        {trailingIcon && size !== "icon" && (
          <span
            aria-hidden="true"
            className="inline-flex shrink-0 items-center justify-center"
            style={{ marginLeft: cfg.iconGap }}
          >
            {trailingIcon}
          </span>
        )}
      </button>

      {/* Screen Reader live region outside button */}
      {isAsyncFlow && (
        <span role="status" aria-live="polite" className="sr-only">
          {currentStatus === "idle" ? "" : activeLabel}
        </span>
      )}
    </>
  );
}

export default Button;

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

